// The setup registry: every feature and connection Switchboard has, in one list.
//
// The welcome is built from it, and anyone who already finished the welcome sees
// entries added later under What's new (top of the rail). So a new feature is never
// skipped: adding a feature or connection means adding its entry here.
// test/setup.test.js fails if a connection (a poller in lib/, or an agent) has none.
//
//   id      stable, never reused
//   kind    'connect' (something to sign in to or turn on) or 'feature' (something to know)
//   title   short name
//   why     one plain sentence: what it does for you
//   uses    which kinds of use it is for (see USES), or 'all'
//   done    (S) => true once it is set up (connect only)
//   open    where "Show me" goes: { pane, focus } in Settings, or { go: '#page', focus, hint },
//           or { cmd: true } for the command bar. focus is an element id to flash;
//           hint is a toast for when there is nothing on the page to point at yet
//   added   date it shipped (YYYY-MM-DD), for ordering What's new

window.USES = [
  { id: 'work', name: 'Work', blurb: 'Email, chats and meetings in one place', projects: [{ name: 'Work', color: '#2F5D8A' }] },
  { id: 'business', name: 'Small business', blurb: 'Customers, invoices and bills', projects: [{ name: 'Business', color: '#FF4F00' }, { name: 'Customers', color: '#8A6D1F', group: 'Clients' }] },
  { id: 'family', name: 'Family and home', blurb: 'Reminders, bills and messages for the household', projects: [{ name: 'Family', color: '#1F7A4D' }, { name: 'Home', color: '#0E7C86' }] },
  { id: 'homestead', name: 'Homestead', blurb: 'Animals, garden, chores and supplies', projects: [{ name: 'Homestead', color: '#8A6D1F' }, { name: 'Animals', color: '#B42318' }, { name: 'Garden', color: '#1F7A4D' }] },
  { id: 'code', name: 'Coding with AI', blurb: 'Claude, Codex and GitHub, without the tab juggling', projects: [{ name: 'Code', color: '#7A3E9D' }] }
];

const agentReady = (S, id) => !!(S.agents || []).find((a) => a.id === id && a.installed && a.signedIn);

window.SETUP = [
  { id: 'ebay', kind: 'connect', title: 'Flips: eBay deals', why: 'It sweeps whole eBay categories for you (graphics cards, consoles, headphones, lenses, power tools and more; no search words needed), pricing every new listing by its product, and watches anything you name too: new Buy It Now listings, misspelled ones ("Milwalkee", "Nintedo") that few buyers find, and auctions about to end. Each shows what it sells for and your profit after eBay\'s fees and shipping, and a new one is an alert. It reads listings with your own free eBay developer keys; buying is always your click on eBay.', uses: 'all',
    done: (S) => !!S.flips?.ebay, open: { go: '#flips', focus: 'flips-setup' }, added: '2026-11-12' },
  { id: 'engine', kind: 'feature', title: 'Chat with the AI on your own computer', why: 'In Sessions, New session, pick Agent: Local AI (Switchboard), no folder needed: a chat with the AI model on this computer, the same one Jarvis thinks with, in the same Chat view as Claude. Nothing you type or show it leaves the computer. It loads onto the graphics card with your first message, making room by unloading other models, and unloads after a few idle minutes; Jarvis and every session share that one loaded copy. Add a picture with the paperclip; Think first lets it work a hard question through. Past chats show under it to pick up again or delete, and clear themselves after 30 days. Pick the model and how much it remembers in Settings, Connections, Local AI models.', uses: 'all', open: { go: '#sessions', hint: 'New session, then Agent: Local AI (Switchboard).' }, added: '2026-11-13' },
  { id: 'flipcheck', kind: 'feature', title: 'Flips: is it a good buy?', why: 'Found something on ShopGoodwill, a garage sale or anywhere? Type what it is and the price, paste its link, or press the Check in Flips bookmark on the listing: it says Good deal, Thin or Bad deal, what it sells for on eBay, your profit after fees, shipping and tax, and the most to pay or bid. Jarvis does it too: "is a Steam Deck for 250 a good deal?"', uses: 'all', open: { go: '#flips', focus: 'flips-check' }, added: '2026-11-12' },
  { id: 'fliplog', kind: 'feature', title: 'Flip log', why: 'Everything you bought to resell, from bought to listed to sold, with the real profit after eBay\'s fee and the label, the money still sitting in what has not sold, and how many days things take to sell. Under Money, Flip log; "I bought it" on a price check adds one.', uses: 'all', open: { go: '#fliplog' }, added: '2026-11-12' },
  { id: 'auctions', kind: 'connect', title: 'Flips: ShopGoodwill and HiBid on the radar', why: 'Save a search on ShopGoodwill and HiBid for what you resell, with email alerts on, and Flips reads those emails as they arrive, prices every item on eBay and alerts you to the ones worth bidding on. Under Money, Flips, Radar. Your mail is read on this computer only.', uses: 'all',
    done: (S) => (S.flips?.mail || 0) > 0, open: { go: '#flips', focus: 'flips-setup' }, added: '2026-11-12' },
  { id: 'gsa', kind: 'feature', title: 'Flips: surplus auctions nearby', why: 'Government surplus auctions (GSA) within driving distance show under Money, Flips: set the ZIP areas you would drive to and it lists what is up for bid there, ending soonest first.', uses: 'all', open: { go: '#flips', focus: 'flips-setup' }, added: '2026-11-12' },
  { id: 'project-dashboards', kind: 'feature', title: 'Project dashboards', why: 'Each project gets a Dashboard tab set up for what it is: a client\'s website (an SEO score, AI search readiness for ChatGPT and Google\'s AI Overviews, tracking and ads tags, speed, site health, fixes worst first), numbers you track by hand (a rating, reviews, leads), the analysis in words, and the change since day one. Make PDF puts a clean report in the project\'s Files.', uses: 'all', open: { go: '#now', hint: 'Open a project (Projects in the ring), then its Dashboard tab.' }, added: '2026-11-11' },
  { id: 'inbox-teams-folder', kind: 'feature', title: 'Every Teams chat in Inbox', why: 'Inbox has a Teams folder with all your recent Teams chats, answered or not: open one to read the whole thread and write in it whenever you like.', uses: ['work', 'business'], open: { go: '#inbox', hint: 'Teams is a folder on the left of Inbox, under Personal.' }, added: '2026-11-11' },
  // ---- connections
  { id: 'account', kind: 'connect', title: 'Switchboard account', why: 'Your setup on every computer you use, encrypted so only you can read it.', uses: 'all',
    done: (S) => !!S.account?.signedIn && !S.account.locked, open: { pane: 'accounts', focus: 'acct' }, added: '2026-11-01' },
  { id: 'projects', kind: 'connect', title: 'Your projects', why: 'Split things by business, client or part of life, so each shows in the right place.', uses: 'all',
    done: (S) => S.spaces.length > 1, open: { pane: 'projects' }, added: '2026-11-01' },
  { id: 'gmail', kind: 'connect', title: 'Gmail', why: 'Mail from people (not ads), sorted by project, with reply and archive.', uses: ['work', 'business', 'family', 'homestead'],
    done: (S) => S.status.gmail.length > 0, open: { pane: 'connections', focus: 'gmail-add' }, added: '2026-11-01' },
  { id: 'email', kind: 'connect', title: 'Any email account', why: 'iCloud, Yahoo, Fastmail, work mail and more, next to Gmail: type the address and Switchboard finds the rest.', uses: ['work', 'business', 'family', 'homestead'],
    done: (S) => S.status.gmail.some((g) => g.kind === 'imap'), open: { pane: 'connections', focus: 'gmail-add' }, added: '2026-11-03' },
  { id: 'calendars', kind: 'connect', title: 'Calendars', why: 'Today\'s events at the top of Now, and a heads-up ten minutes before each. Google, Outlook, iCloud, school and team calendars.', uses: 'all',
    done: (S) => (S.calendars || []).length > 0, open: { pane: 'connections', focus: 'cal-card' }, added: '2026-11-03' },
  { id: 'weather', kind: 'connect', title: 'Weather', why: 'One line on Now, plus rain coming, frost tonight, and official warnings where you are.', uses: 'all',
    done: (S) => !!S.weather, open: { pane: 'look', focus: 'weather-field' }, added: '2026-11-03' },
  { id: 'webhooks', kind: 'connect', title: 'Links for other apps (webhooks)', why: 'A private link that IFTTT, Zapier, Home Assistant, a phone shortcut or a script can use to put a note, a reminder or a "needs you" on your board.', uses: 'all',
    done: (S) => (S.webhooks || 0) > 0, open: { pane: 'connections', focus: 'hook-card' }, added: '2026-11-03' },
  { id: 'microsoft', kind: 'connect', title: 'Teams and Outlook', why: 'Work chats and mail; reply without opening Teams.', uses: ['work', 'business'],
    done: (S) => !!S.status.microsoft?.connected, open: { pane: 'connections', focus: 'ms-card' }, added: '2026-11-01' },
  { id: 'github', kind: 'connect', title: 'GitHub', why: 'Pull requests to review and builds that failed.', uses: ['code'],
    done: (S) => S.status.github.ok === true, open: { pane: 'connections', focus: 'dev-cards' }, added: '2026-11-01' },
  { id: 'claude', kind: 'connect', title: 'Claude Code', why: 'See which sessions need you, and run them inside Switchboard.', uses: ['code'],
    done: (S) => !!S.status.hooks, open: { pane: 'connections', focus: 'dev-cards' }, added: '2026-11-01' },
  { id: 'codex', kind: 'connect', title: 'ChatGPT (Codex)', why: 'OpenAI\'s coding agent, signed in with your ChatGPT plan. Its sessions read like a chat too: messages, the commands it runs and the files it edits.', uses: ['code'],
    done: (S) => agentReady(S, 'codex'), open: { pane: 'connections', focus: 'dev-cards' }, added: '2026-11-03' },
  { id: 'browser-checks', kind: 'connect', title: 'Browser checks', why: 'Your project\'s own browser tests, or a page that has to load and show the right text, run in a browser with no window that closes after each run, on a click or every hour or day. A failure is a Needs-you card with the failing tests and screenshots. Set up the checking browser from Browser checks, once; your agents get the same browser. A project\'s tests can run signed in to a site that needs it: you sign in yourself in a window on your computer, and Switchboard never sees your password.', uses: ['code'],
    done: (S) => (S.checks || []).length > 0, open: { go: '#checks' }, added: '2026-11-03' },
  { id: 'gemini', kind: 'connect', title: 'Gemini', why: 'Google\'s coding agent, signed in with your Google account.', uses: ['code'],
    done: (S) => agentReady(S, 'gemini'), open: { pane: 'connections', focus: 'dev-cards' }, added: '2026-11-03' },

  // ---- features worth knowing
  { id: 'calendar-page', kind: 'feature', title: 'Calendar', why: 'A month of everything on your calendars, with the day you pick opened underneath. Sign in with Google (Settings, Connections, Calendars) and you can add, change and delete events here too.', uses: 'all', open: { go: '#calendar', hint: 'Pick a day to see its events; the arrows move by month.' }, added: '2026-11-04' },
  { id: 'notebook', kind: 'feature', title: 'Notebook', why: 'Notes, Pages: write with a formatting bar like an email (headings, bold, bullets, checklists). End a line with = for the answer; "shopping eggs" in Ctrl K adds to your Shopping list; "log eggs 14" keeps a running total.', uses: 'all', open: { go: '#notes', hint: 'Pages is the first tab on Notes. New page starts one, or pick a template.' }, added: '2026-11-03' },
  { id: 'routines', kind: 'feature', title: 'Chores and routines', why: 'Things that come back on their own: "walk the dog every day at 6am and 6pm", "filter every 90 days". They show on Now when due; Done sets the next one. Notes has ideas to pick from.', uses: 'all', open: { go: '#notes', hint: 'The Routines tab on Notes has the ideas to pick from, or type one into Ctrl K.' }, added: '2026-11-03' },
  { id: 'deliveries', kind: 'feature', title: 'Packages', why: 'Shipping emails become one line each on Now: arriving Thursday, out for delivery 10 to 2, delivered, or delayed. Click one to track it.', uses: 'all', open: { go: '#now', hint: 'Packages show in the Today card at the top of Now as soon as a shipping email arrives.' }, added: '2026-11-03' },
  { id: 'conversations', kind: 'feature', title: 'Conversations, like Teams', why: 'Pick a conversation in Inbox and it opens large beside the list, live: new Teams messages show within seconds, your reply shows the moment you send it, and nothing jumps while you read.', uses: ['work', 'business', 'family'], open: { go: '#inbox', hint: 'Pick any conversation in the list and it opens here, large.' }, added: '2026-11-03' },
  { id: 'desktop-app', kind: 'feature', title: 'Switchboard as an app', why: 'Download it, double-click, and Switchboard has its own icon and window, sits in the tray when closed, starts at login and updates itself. No terminal, no browser.', uses: 'all', open: { go: '#now', hint: 'The app is on the Switchboard download page. This page keeps working as it is.' }, added: '2026-11-03' },
  { id: 'people-many', kind: 'feature', title: 'One person, every address', why: 'On a project\'s About card, a person can have a work email and a Gmail, and as many phone numbers as they use: Add email and Add phone under each person. Mail from any of their addresses, and texts from any of their numbers, sort into that project. Two rows that are the same person? Merge with… makes them one and keeps every address.', uses: 'all', open: { go: '#now', hint: 'Open a project from the left, then Edit on its About card.' }, added: '2026-11-05' },
  { id: 'web-board', kind: 'feature', title: 'Switchboard in a browser', why: 'At your own domain, with nothing to install: your own projects, notes and to-dos, Teams, Outlook and GitHub, and the projects shared with you, kept in your account and opened only in your browser. The invite button opens it; making the account there is joining.', uses: ['work', 'business', 'family'], open: { pane: 'team', hint: 'Invite someone from Team: the button in their email opens the board, when your Switchboard account\'s service has one.' }, added: '2026-11-05' },
  { id: 'share-everything', kind: 'feature', title: 'Share everything a project has', why: 'Give a co-founder everything in a project with one button: its pages and sections, to-dos, repos and builds, browser checks, activity, your sessions live (they can ask to send; you let it in), its conversations, calendar, money and files. Each one None, See or Edit on its own.', uses: ['work', 'business'], open: { pane: 'team', hint: 'Each person\'s projects in Team have Give everything, and a switch per kind.' }, added: '2026-11-05' },
  { id: 'web-connections', kind: 'feature', title: 'Gmail, Google Calendar, Microsoft 365 and GitHub on the web board', why: 'Anyone on the web board connects their own Google (Gmail in Inbox, replies on your click, Google calendars on Calendar), Microsoft 365 (any work, school or personal account: Outlook mail, and Teams for work accounts) and GitHub, in Settings, Account. Kept sealed in your own account.', uses: 'all', open: { pane: 'accounts', focus: 'acct', hint: 'On the web board: Settings, Account, Your connections, here.' }, added: '2026-11-06' },
  { id: 'web-board-full', kind: 'feature', title: 'More of Switchboard in a browser', why: 'On the web board, the projects shared with you now bring their Sessions (follow them live and send to them), Builds, Browser checks, Calendar and Money, on the same pages as the app, with whatever the person who shares them chose.', uses: ['work', 'business', 'family'], open: { pane: 'team', hint: 'Give someone more in Settings, Team: each kind is See, Edit or None. On the board they show on Sessions, Calendar and Money.' }, added: '2026-11-06' },
  { id: 'password-reset', kind: 'feature', title: 'Forgot password', why: 'Forgot the password to your Switchboard account? Whoever runs a project you share presses Reset their password on your card in Settings, Team and gives you a one-time code; press Forgot password? under the sign-in, enter it with a new password, and you are in. Your data stays locked to you: your computers sign out, and each one sends its copy up again when you sign in on it with the new password.', uses: 'all', open: { pane: 'team', hint: 'Settings, Team: Reset their password is on each person\'s card. Forgot password? sits beside Sign in, in Settings, Account.' }, added: '2026-11-06' },
  { id: 'team-chat', kind: 'feature', title: 'Team chat', why: 'A chat for each shared project and one-to-one chats with your teammates, in the Inbox beside your email and Teams. See who has read each message and who is typing, edit or delete your own, reply to a message, @mention someone (they get an alert and a push on their phone) and pin what matters. Encrypted end to end: the sync service holds only sealed lines.', uses: ['work', 'business', 'family'], open: { go: '#inbox', hint: 'Inbox: the Team chat chips above the list open a project\'s chat or one with a teammate. Share a project first (Settings, Team).' }, added: '2026-11-05' },
  { id: 'team', kind: 'feature', title: 'Your team', why: 'Settings, Team: invite someone by email once, even before they have Switchboard (the link makes their account and puts them in). Pick their projects and, for pages, to-dos, repos, activity and the About card, None, See or Edit. Shared repos open in Codespaces or as a ZIP, with nothing to install. Encrypted end to end; never mail, terminals or sign-ins.', uses: ['work', 'business', 'family'], open: { pane: 'team', hint: 'Invite someone is at the top of Team; each person\'s projects and what they can do are below.' }, added: '2026-11-05' },
  { id: 'check-codes', kind: 'feature', title: 'Check codes for your team', why: 'Switchboard keeps the keys of everyone you share with the first time it sees them, and refuses to lock anything to keys that change, with a warning in Team. Check codes let two people read each other a short code to be sure the keys are theirs.', uses: ['work', 'business', 'family'], open: { pane: 'team', hint: 'Check codes is at the end of Team.' }, added: '2026-11-05' },
  { id: 'in-this-project', kind: 'feature', title: 'What belongs to each project', why: 'Each project\'s page starts with In this project: its repos, the people, addresses and chats about it, and the pages (or single sections of pages) for it. Add to this project searches everything; anything can be in more than one project, and a note can be tied to one repo.', uses: 'all', open: { go: '#now', hint: 'Open a project on the left: In this project is at the top, with Add to this project.' }, added: '2026-11-05' },
  { id: 'unsorted', kind: 'feature', title: 'Unsorted, and Hide', why: 'Unsorted, under your projects on the left, lists the repos, folders, people and chats with no project yet: one click files each in its likely project. Hide takes clutter, like folders that are not repos, out of every list and the folder picker. Nothing is deleted.', uses: 'all', open: { go: '#unsorted' }, added: '2026-11-05' },
  { id: 'session-notes', kind: 'feature', title: 'Your notes beside your sessions', why: 'Under a session\'s messages: the notes for its project, and those tied to its repo. Add to message puts a page or one section in what you are writing. Your agents can read them too.', uses: ['code'], open: { go: '#sessions', hint: 'Open a session: its project\'s notes are under its messages on the right.' }, added: '2026-11-05' },
  { id: 'ctrlk-targets', kind: 'feature', title: 'Ctrl K: note and sesh', why: 'From any page: "note call Sam" puts a checkbox at the bottom of a page you pick (or a new one), and "sesh add a test" sends a message to a session you pick. You stay where you are.', uses: 'all', open: { cmd: true }, added: '2026-11-05' },
  { id: 'teams-pictures', kind: 'feature', title: 'Pictures and files in Inbox, in and out', why: 'Pictures people send show as pictures in Inbox: in email, Google Voice texts, Outlook and Teams. Other attachments (a PDF, a spreadsheet) show with their name and size; click to save one. Paste, drop or attach pictures in a reply and they arrive as real pictures: attached to an email or an Outlook reply, inline in Teams. Teams chats also show emoji reactions: hover a message to react with 👍 ❤️ 😆 😮 😢 🙏, or click one to add or take back yours.', uses: ['work', 'business', 'family'], open: { go: '#inbox', hint: 'Open a conversation: the paperclip is beside Send, and in Teams the reactions show when you hover a message.' }, added: '2026-11-05' },
  { id: 'open-in-browser', kind: 'feature', title: 'Open Switchboard in your browser', why: 'If the app\'s window is slow to type or scroll in on your computer, Switchboard says so and offers Open in browser: the same Switchboard, sessions and settings in Chrome, Edge or Brave, with your browser\'s saved passwords. On Linux the app uses your Chrome window on its own. The button is also in Settings, General, and in the app\'s tray menu.', uses: 'all', open: { pane: 'look', hint: 'Open in browser is under About, at the bottom of General, in the app.' }, added: '2026-11-05' },
  { id: 'remove-switchboard', kind: 'feature', title: 'Remove Switchboard cleanly', why: 'Settings, General, Remove takes out everything Switchboard added to this computer (Switchboard\'s links into Claude Code, its tools in your other coding agents, start at login) and leaves your own settings as they are. Tick the box to delete your data too.', uses: 'all', open: { pane: 'look', hint: 'Remove is at the bottom of General, under About.' }, added: '2026-11-05' },
  { id: 'app-updates', kind: 'feature', title: 'Updates in the app, one click', why: 'In the Switchboard app, Update ready shows at the bottom of the page when there is a new version, like it does everywhere else: click it and the app downloads it and restarts. Settings, About has Check for updates, and a switch to install updates on their own when no agent is working.', uses: 'all', open: { pane: 'look', hint: 'Check for updates and the switch are under About, at the bottom of General.' }, added: '2026-11-05' },
  { id: 'connection-list', kind: 'feature', title: 'Only the connections you use', why: 'Settings, Connections now shows just yours. Everything else is under Add a connection, by kind (Messages, Calendars, Money, Coding, Automation), with Add; Remove from list takes back one you are not using.', uses: 'all', open: { pane: 'connections', hint: 'Your connections are at the top; Add a connection is below them.' }, added: '2026-11-05' },
  { id: 'drafts', kind: 'feature', title: 'Email drafts, editable in Inbox', why: 'Drafts in your mail, including ones an assistant wrote for you, show in Inbox: in the conversation they answer, or at the top of Inbox. Edit, then Send, Save draft (back to your Drafts, so Gmail shows the same) or Discard.', uses: ['work', 'business', 'family'], open: { go: '#inbox', hint: 'Drafts are listed at the top of Inbox; one that answers a conversation also shows at the bottom of it.' }, added: '2026-11-05' },
  { id: 'file-links', kind: 'feature', title: 'Click a file to read it', why: 'When an agent names a file (a document, a screenshot, a line of code), in Chat or Terminal view, click it: Switchboard shows it right there, a document as a page and code with that line lit, with Open in its own app and Show in folder. Pictures it sends show in the chat.', uses: ['code'], open: { go: '#sessions', hint: 'In a session, file names with a blue underline open with a click (in Terminal view the underline shows when the mouse is over one).' }, added: '2026-11-05' },
  { id: 'search', kind: 'feature', title: 'Search everything', why: 'Ctrl K, then type a few letters: sessions (on every computer), people on your projects, emails and Teams chats, calendar events, bills and charges, pages and notes, projects, and Switchboard\'s own features. Arrow down and Enter opens one; Enter on its own still adds what you typed as a note.', uses: 'all', open: { cmd: true }, added: '2026-11-05' },
  { id: 'jarvis', kind: 'feature', title: 'Jarvis: talk to Switchboard', why: 'Hold Ctrl+Space anywhere and say it: "what needs me", "go to builds", "open the switchboard session", "remind me tomorrow at 9 to call the bank", or ask a session to do something. It answers out loud and does it. The common things work at once with no AI; anything else goes to the AI model on this computer (Switchboard runs it, or LM Studio or Ollama), so it is free and private.', uses: 'all', open: { jarvis: true }, added: '2026-11-08' },
  { id: 'jarvis-fast', kind: 'feature', title: 'Jarvis answers in under a second', why: 'He starts talking as soon as his first sentence is ready, the model loads while you are still holding Ctrl+Space, and holding it again while he talks stops him. A short tone says he is listening, another that he heard you.', uses: 'all', open: { jarvis: true }, added: '2026-11-08' },
  { id: 'jarvis-speakup', kind: 'feature', title: 'Jarvis speaks up', why: 'Switch it on and he says out loud when a session needs you, and when sessions finish ("Two done: notes page and inbox fix"). Ask "what did the switchboard session say" and he reads the start; "read it all" reads the rest.', uses: ['code'], open: { pane: 'look', hint: 'Settings, General, Jarvis: "Say out loud when a session finishes or needs you".' }, added: '2026-11-08' },
  { id: 'jarvis-brief', kind: 'feature', title: 'A spoken morning brief', why: 'On your first click of the day Jarvis says the weather, what is on the calendar, what needs you, sessions waiting, builds that failed overnight, mail waiting and bills due. Say "brief me" or "good morning" for it any time.', uses: 'all', open: { pane: 'look', hint: 'Settings, General, Jarvis switches it on or off.' }, added: '2026-11-08' },
  { id: 'jarvis-memory', kind: 'feature', title: 'Jarvis remembers', why: 'Say "remember that my sister Ana lives in Denver" and he uses it from then on; "forget…" takes it out, and "what did I say about the bank?" finds earlier words. Each night he tidies his notes about you, kept short so he stays quick. Settings shows them to edit, with Undo.', uses: 'all', open: { pane: 'look', hint: 'Settings, General, What Jarvis knows.' }, added: '2026-11-08' },
  { id: 'usage', kind: 'feature', title: 'AI plan limits, with a forecast', why: 'The Deck and Now show your Claude plan\'s 5-hour and weekly limits as small charts: how much is used, when each resets, and where your pace lands by then ("On track, lands near 77%" or "Runs out about 7:20 PM at this pace"), with what each day of the week used. A Claude session\'s bar on Sessions has a tiny gauge for each. Codex shows too once you use it. It reads what Claude Code already reports, so there is nothing to connect.', uses: ['code'], open: { go: '#deck', hint: 'AI plans is the wide module across the bottom of the Deck. It fills in once a Claude Code session is running.' }, added: '2026-11-08' },
  { id: 'usage-page', kind: 'feature', title: 'AI plans: your usage, history and habits', why: 'Click the AI plans card for its own page, on one screen: a big chart of the week you can hover for any moment (with last week\'s line to compare), when in the week you use the plan, every past week and where it ended (click one to see it again), the last four weeks day by day, your habits (a day\'s use, an hour of real use, busiest day and hour) and the sessions that made the biggest dents. A tab for each plan you have.', uses: ['code'], open: { go: '#usage', hint: 'Or click the AI plans card on the Deck or Now. It fills in as Claude Code sessions run.' }, added: '2026-11-09' },
  { id: 'capture', kind: 'feature', title: 'Type it once', why: 'Ctrl K, then "remind me to call Sam at 3", "bill rent 1200 on the 1st" or "note gate code 4411".', uses: 'all', open: { cmd: true }, added: '2026-11-01' },
  { id: 'voice', kind: 'feature', title: 'Talk to type', why: 'Click the mic next to any message box and talk. Enter stops, Enter again sends. Settings, General, Microphone picks which mic it listens to (an audio interface or a headset, if your computer\'s default is another).', uses: 'all', open: { pane: 'look' }, added: '2026-11-03' },
  { id: 'theme', kind: 'feature', title: 'Text size', why: 'Settings, General: bigger or smaller text, everywhere but the terminal (which has its own size).', uses: 'all', open: { pane: 'look' }, added: '2026-11-03' },
  { id: 'hud', kind: 'feature', title: 'The Command Deck', why: 'Switchboard opens on the Deck: Jarvis at the centre, every system around it as a live module (needs you, sessions, builds, inbox, calendar, money, notes, checks, projects). Click a module and it opens into its full panel; Esc, the wordmark or "back" returns. Pages, projects, search and settings sit in the ring across the top. Orange still means one thing: it needs you.', uses: 'all', open: { go: '#deck' }, added: '2026-11-08' },
  { id: 'everywhere', kind: 'feature', title: 'Sessions on every computer', why: 'Sign in on each computer and every session shows on all of them.', uses: ['code'], open: { go: '#sessions', hint: 'Sign in on another computer (Settings, Account) and its sessions join the list on the right.' }, added: '2026-11-02' },
  { id: 'actions', kind: 'feature', title: 'GitHub Actions, live', why: 'Sessions, Builds shows every run as it goes: yellow while it runs, green passed, red failed. Each session shows its own repo\'s runs too.', uses: ['code'], open: { go: '#builds' }, added: '2026-11-03' },
  { id: 'mcp', kind: 'feature', title: 'Your agents can use Switchboard', why: 'Claude, Codex and Gemini get Switchboard\'s tools: they can see what needs you and your builds, put a needs-you card on the board when they are blocked, and hand work to another session.', uses: ['code'], open: { go: '#sessions', hint: 'Ask an agent "what needs me on Switchboard?". It has the tools after you finish Claude Code setup in Settings, Connections.' }, added: '2026-11-03' },
  { id: 'session-tree', kind: 'feature', title: 'Sessions as lines, with your own names', why: 'Every session is one line on the right, under the repo it works in, named by what it is working on and saying what it is doing. Double-click a line (or More, Rename) to give it your own name; clear the name to go back.', uses: ['code'], open: { go: '#sessions', hint: 'Your sessions are the lines on the right, under the repo each works in.' }, added: '2026-11-03' },
  { id: 'bring-message', kind: 'feature', title: 'Bring one message into a session', why: 'Messages, beside the paperclip on Sessions, lists the recent emails, texts and Teams chats in the session\'s project, with a search. Click one to add just that message, with who sent it and when. Link to a project on a conversation from elsewhere, and that person\'s messages go to that project from then on.', uses: ['code'], open: { go: '#sessions', focus: 'q-bring', hint: 'Open a session first: Messages sits beside the paperclip under the message bar.' }, added: '2026-11-03' },
  { id: 'session-chat', kind: 'feature', title: 'Sessions read like a chat', why: 'A Claude session opens as a conversation with one message bar, like the Claude and ChatGPT apps. When Claude asks permission or offers choices, they show as buttons in the chat; write a message instead and it answers No and sends yours. While it works you see what it is doing. Prefer Claude\'s own terminal? Settings, General, Sessions open in: Chat or Terminal; Chat | Terminal on a session switches just that one.', uses: ['code'], open: { pane: 'look' }, added: '2026-11-03' },
  { id: 'images', kind: 'feature', title: 'Paste images to an agent', why: 'Paste or drop a screenshot into the message bar on Sessions.', uses: ['code'], open: { go: '#sessions', focus: 'q-attach', hint: 'Open a session first: the paperclip under the message bar adds an image, or paste one straight in.' }, added: '2026-11-03' },
  { id: 'notes-voice', kind: 'feature', title: 'Talk to type in Notes', why: 'A mic on a page\'s formatting bar puts your words in where the caret is (one undo takes them out), and one on the Quick notes box. In Ctrl K, "today picked up the parts" puts a timed line on today\'s page in the project you are in.', uses: 'all', open: { go: '#notes', hint: 'Open a page: the mic is the last button on the formatting bar. Quick notes has one beside Add.' }, added: '2026-11-04' },
  { id: 'notes-send-line', kind: 'feature', title: 'Send just the bullet you are on', why: 'In a page, a small arrow at the end of the line you are on sends that bullet (and the ones under it) to a session; select a few bullets and it sends those. Whole page is still one click in the dialog.', uses: ['code'], open: { go: '#notes', hint: 'Open a page and click into a bullet: the arrow is at the end of the line.' }, added: '2026-11-06' },
  { id: 'notes-send', kind: 'feature', title: 'Send a page to a session', why: 'Send to session on a page (or a quick note) sends the whole page, the text you selected, or the line you are on. You see what goes and can change it, and you can add a line like "Turn this into a plan". Send puts it in now, or queues it while the agent is busy. Edit in the message bar opens it there instead.', uses: ['code'], open: { go: '#notes', hint: 'Open a page: Send to session sits beside Pin. On Quick notes each note has one.' }, added: '2026-11-04' },
  { id: 'other-computer-session', kind: 'feature', title: 'A session from your other computer, as if it were here', why: 'Open a session that runs on your other computer and it shows as a chat too, with its questions as buttons. What you copy in its terminal lands on the computer you are using, not the one it runs on.', uses: ['code'], open: { go: '#sessions', hint: 'Sign in on both computers and turn on sharing sessions in Settings, Account; their sessions then show on Sessions.' }, added: '2026-11-04' },
  { id: 'model-effort', kind: 'feature', title: 'Pick the model and effort, type / for commands', why: 'New session asks which Claude model (Sonnet, Opus, Haiku, 1M context) and how hard it should think, remembered per folder. In the message bar, type / to list Claude\'s commands and the project\'s own shortcuts (skills) with what each does; /model opens Claude\'s picker as buttons in the chat. The session\'s bar shows its model, effort, context used and cost as it runs (after you finish Claude Code setup in Settings, Connections).', uses: ['code'], open: { go: '#sessions', hint: 'New session has Model and Effort under Folder. In a Claude session, type / in the message bar to see the commands; the readout sits on the session\'s bar.' }, added: '2026-11-04' },
  { id: 'new-face', kind: 'feature', title: 'A new face and logo', why: 'Switchboard has a new logo (three streams meeting at one lamp) and its own typefaces now (a warm serif for titles, a plain sans for text, one mono for readouts and the terminal), shipped with it so nothing loads from Google, and the lamp in the wordmark lights up when something needs you. Light and dark are set in Settings, General.', uses: 'all', open: { pane: 'look', hint: 'Theme and text size are at the top of Settings, General. The lamp beside the name is orange when something needs you and green when all is clear.' }, added: '2026-11-04' },
  { id: 'system-monitor', kind: 'feature', title: 'System monitor', why: 'See how busy this computer is: processor, memory, graphics, network, storage, temperatures, fans and the apps using the most, with a line in words about what is slowing it down. Settings, System, Open the monitor.', uses: 'all',
    open: { pane: 'system', focus: 'sys-open' }, added: '2026-11-04' },
  { id: 'end-apps', kind: 'feature', title: 'End programs from the System monitor', why: 'The monitor marks every app Safe to end, Ask first (a session is using it, it may have unsaved work, or it is busy) or Keep (part of the system). Click an app to see each of its processes: what it is, which session or folder it belongs to, how long it has been open, the ports it serves and the memory and video memory it holds, with End on each. End asks it to close; if it will not, Force end makes it. Anything big sitting idle is named at the top with an End button. Linux for now. Ask Jarvis "what\'s using my memory" or "end comfyui".', uses: 'all',
    open: { pane: 'system', focus: 'sys-open', hint: 'Open the monitor, then click any app in the Apps list.' }, added: '2026-11-12' },
  { id: 'books', kind: 'feature', title: 'Books: a library you read here', why: 'Inbox, Reading is a library now. Add book searches archive.org for books that are free to download (or paste a book\'s link), and the book opens on its own scanned pages, where you left off. Drag across words to highlight them in four colours or add a note; B bookmarks a page; Text shows the page as plain text, Page shows two pages side by side like an open book, Night dims the paper. Shelves (reading, want to read, finished) and tags keep it arranged. Read aloud reads it to you a sentence at a time, the words lit as it goes, and keeps going while you work on other pages; or play the book\'s free LibriVox audiobook, chapter by chapter. Ask Jarvis "continue reading", "read to me", "stop reading".', uses: 'all', open: { go: '#inbox' }, added: '2026-11-10' },
  { id: 'readaloud', kind: 'connect', title: 'Read-aloud voice', why: 'A natural voice that runs on this computer (Piper: free, open source, works offline) reads your books aloud, and Jarvis can speak with it too. Pick a voice, Install, and it downloads once (60 to 145 MB). Without it, books are read with the computer\'s built-in voice.', uses: 'all',
    done: (S) => !!S.voice?.installed, open: { pane: 'connections', focus: 'voice-card' }, added: '2026-11-10' },
  { id: 'inbox-folders', kind: 'feature', title: 'Inbox, like a mail app', why: 'Inbox fits on one screen in three columns: folders on the left (Business, Personal, Drafts, Replied, Tracking, Reading, and your team chats), the folder\'s list in the middle with two short lines per conversation, and the open conversation on the right with the reply box under it. No more rows of filters or drafts piled above your mail. Esc closes a conversation and keeps you on Inbox.', uses: 'all', open: { go: '#inbox' }, added: '2026-11-10' },
  { id: 'mailtrack', kind: 'connect', title: 'Mail tracking', why: 'See when email you send from Switchboard is opened and clicked, and whether it was really a person (with the reasons), on Inbox, Tracking; a new open is an alert. Mail from people who track you is marked "Tracks you", and you get an alert. It works with your own mail tracker on Cloudflare: type its address and paste an access token from it. Switchboard shows mail as text, so their trackers never load here.', uses: 'all',
    done: (S) => !!S.mailtrack?.connected, open: { pane: 'connections', focus: 'mailtrack-card' }, added: '2026-11-10' },
  { id: 'calendar-say-it', kind: 'feature', title: 'Add to and change your calendar by typing or saying it', why: 'In Ctrl K or to Jarvis, one line puts an event on your Google calendar: "lunch with Sam fri noon to my calendar", "meeting dentist tue 3-4pm", "schedule oil change tomorrow" (no time is all day), "add Mia\'s recital to the family calendar 11/20 6pm". Ask Jarvis "what\'s on my calendar tomorrow" or "am I free friday". Change them the same way: "move lunch with Sam to 1pm", "reschedule dentist to thu 2-3pm", "rename the dentist event to cleaning", "cancel lunch with Sam friday" (it asks first). It stays in sync with Google both ways: what you change on your phone shows here within about a minute. The Calendar page always has Add event now; it shows how to connect a Google calendar when none can take events yet.', uses: 'all', open: { go: '#calendar' }, added: '2026-11-10' },
  { id: 'jarvis-everything', kind: 'feature', title: 'Jarvis can do anything Switchboard can', why: 'Ask Jarvis for anything on the page, not only the common things: connect or change a calendar, set the weather units, file something into a project, run a browser check, add a routine, archive a conversation, run the network test and more. He finds the action by what you said and does it. Anything that removes waits for your yes, and anything that would reach another person (a reply, a chat, an invitation) is left for you to send. Hold Ctrl+Space and ask.', uses: 'all', open: { go: '#deck' }, added: '2026-11-10' },
  { id: 'network-test', kind: 'feature', title: 'Network test', why: 'A speed test built in: download and upload on 8 connections at once, latency, jitter, packet loss, and bufferbloat (how far latency rises while the line is busy, which is what makes calls stutter), with what the result is good for in plain words and every past test kept on this computer. It runs from this computer against Cloudflare\'s nearest server, not in the browser, and checks your router too, so you can tell Wi-Fi trouble from internet trouble. Settings, System, Test the network, or Test speed on the monitor.', uses: 'all',
    open: { pane: 'system', focus: 'st-open' }, added: '2026-11-10' },
  { id: 'project-pages', kind: 'feature', title: 'Every project has its own page', why: 'Click a client or project on the left and it opens its own page: what is in flight, its conversations, sessions, notes and files (drop them on the page), and on the side who it is for, how to reach them (everyone you have written to in that project is offered from your mail, Add or Hide) and links to their site, its admin and anything else you open for them. To narrow a list to one project, use the picker at the top of that page.', uses: 'all', open: { go: '#now', hint: 'Click any project on the left to open its page. Edit on its About card adds people and links.' }, added: '2026-11-04' },
  { id: 'feeds', kind: 'connect', title: 'News and blogs', why: 'Follow sites and blogs (type the site, Switchboard finds its feed) and their newest posts show on Inbox, Reading: quietly, never as something that needs you.', uses: 'all',
    done: (S) => (S.reading || []).length > 0, open: { pane: 'connections', focus: 'feeds-card' }, added: '2026-11-04' },
  { id: 'localai', kind: 'connect', title: 'Local AI models', why: 'Run AI models on this computer with Ollama: private, free, and they work offline. Install it and get a model from Settings, Connections, then start one from New session (Agent: Local model). It reads like a chat, the same as a Claude session. LM Studio and other local servers show there too.', uses: ['code'],
    done: (S) => (S.agents || []).some((a) => a.id === 'localai' && a.installed), open: { pane: 'connections', focus: 'local-ai-card' }, added: '2026-11-04' },
  { id: 'session-messages', kind: 'feature', title: 'Messages beside your sessions', why: 'Under the session list on Sessions: the newest email and Teams conversations for the session\'s project (a new one has an orange dot). Add to message puts one into what you are sending the agent; Earlier shows the conversation; Hide or Clear all keeps the list short until someone writes again.', uses: ['code'], open: { go: '#sessions', hint: 'Open a session: Messages is under the session list on the right.' }, added: '2026-11-04' },
  { id: 'chat-questions', kind: 'feature', title: 'Claude\'s questions in the chat', why: 'When Claude asks you to choose (one answer, several, or your own words), the choices show in the chat with their descriptions: tick boxes for several, Type something to write your own, and a review before it goes. No switching to the terminal.', uses: ['code'], open: { go: '#sessions', hint: 'Its next question shows at the end of the chat.' }, added: '2026-11-04' },
  { id: 'file-reader', kind: 'feature', title: 'Look at files without downloading them', why: 'A project\'s files and the files in your notes open inside Switchboard: pictures, PDFs and text, with Download, Copy, and Move or copy to another project, a note or a session.', uses: 'all', open: { go: '#notes', hint: 'Open a project and click one of its files, or double-click a picture in a note.' }, added: '2026-11-06' },
  { id: 'files', kind: 'feature', title: 'Files and pictures anywhere', why: 'Drop, paste or pick any file: into a session (the agent gets it), onto its terminal, into a note (pictures show in the page), or onto a project. Up to 1 GB each; they stay on this computer.', uses: 'all', open: { go: '#notes', hint: 'In a note, use the paperclip on the toolbar, or drop a picture onto the page.' }, added: '2026-11-04' },
  { id: 'oops', kind: 'feature', title: 'Problems say so', why: 'If something on the page breaks, a line at the bottom says so with Copy details: the version, the page and the error, ready to paste into a bug report. Nothing is sent anywhere.', uses: 'all', open: { go: '#now', hint: 'Nothing to set up: it shows only when something goes wrong.' }, added: '2026-11-04' },
  { id: 'keys', kind: 'feature', title: 'Keyboard shortcuts', why: 'Press ? for every shortcut. G then a letter goes to a page: G N Now, G S Sessions, G I Inbox, G M Money, G O Notes. In a Claude session\'s terminal, Shift+Enter is a new line and Ctrl+Enter sends now.', uses: 'all', open: { go: '#now', hint: 'Press ? anywhere outside a text box.' }, added: '2026-11-04' },
  { id: 'undo', kind: 'feature', title: 'Undo', why: 'Done, Delete and archiving a conversation can be taken back for a few seconds: Undo on the line at the bottom, or Ctrl+Z.', uses: 'all', open: { go: '#inbox', hint: 'Mark something done, delete it or archive a conversation: Undo shows at the bottom.' }, added: '2026-11-04' },
  { id: 'rundown', kind: 'feature', title: 'Morning rundown', why: 'Until noon, the top of Now says how the day looks in one sentence: meetings, what needs you, bills this week, packages and routines, with the weather and the schedule. Read aloud uses a voice on your computer. Done for today puts it away; Rundown on the Today card brings it back.', uses: 'all', open: { go: '#now', hint: 'Mornings it sits at the top of Now. Any other time, press Rundown on the Today card.' }, added: '2026-11-04' },
  { id: 'granola', kind: 'connect', title: 'Granola', why: 'Your Granola meeting notes in Notes, one page a meeting with its summary and your own notes, in the project it belongs to (a Granola folder named like the project, the people in it, or its title), so you and your sessions can read them. Read only. Sign in on Granola\'s own page, any plan, the free one too.', uses: ['work', 'business', 'code'],
    done: (S) => !!S.granola?.connected, open: { pane: 'connections', focus: 'granola-card' }, added: '2026-11-06' },
  { id: 'tasks', kind: 'connect', title: 'Todoist', why: 'Your Todoist tasks due today or overdue show on Now, in the project you pick; Done there ticks them off in Todoist (a repeating one moves to its next date). Paste your Todoist key: the card walks you through it.', uses: 'all',
    done: (S) => !!S.taskStatus?.todoist?.connected, open: { pane: 'connections', focus: 'tasks-card' }, added: '2026-11-04' },
  { id: 'trello', kind: 'connect', title: 'Trello', why: 'Cards with a due date, on boards you are on, show on Now when due; Done there marks them complete in Trello. Paste two codes from Trello: the card walks you through it.', uses: 'all',
    done: (S) => !!S.taskStatus?.trello?.connected, open: { pane: 'connections', focus: 'trello-card' }, added: '2026-11-05' },
  { id: 'asana', kind: 'connect', title: 'Asana', why: 'Tasks assigned to you, due today or overdue, show on Now; Done completes them in Asana. Paste an Asana key: the card walks you through it.', uses: ['work', 'business'],
    done: (S) => !!S.taskStatus?.asana?.connected, open: { pane: 'connections', focus: 'asana-card' }, added: '2026-11-05' },
  { id: 'notion', kind: 'connect', title: 'Notion', why: 'Pages in your Notion task database with a date of today or earlier show on Now; Done ticks them off in Notion. Paste a Notion key and share your task database with it: the card walks you through it.', uses: 'all',
    done: (S) => !!S.taskStatus?.notion?.connected, open: { pane: 'connections', focus: 'notion-card' }, added: '2026-11-05' },
  { id: 'lmstudio', kind: 'connect', title: 'LM Studio models as sessions', why: 'If you use LM Studio, the models you downloaded there start from New session (Agent: Local model (LM Studio)) and chat in a terminal: on this computer, private and offline. Settings, Connections, Local AI models lists them.', uses: ['code'],
    done: (S) => (S.agents || []).some((a) => a.id === 'lmstudio' && a.installed), open: { pane: 'connections', focus: 'local-ai-card' }, added: '2026-11-04' },
  { id: 'unload-models', kind: 'feature', title: 'Unload local AI models with a click', why: 'Settings, Connections, Local AI models lists what LM Studio has loaded right now, and models Bionic holds (size, status, how long it has sat idle) with Unload and Unload all, to free the graphics card. Jarvis\'s own model still unloads itself after a few idle minutes; one you loaded yourself stays until you press Unload, with a quiet note after 30 idle minutes. Or say "unload models".', uses: ['code'], open: { pane: 'connections', focus: 'local-ai-card' }, added: '2026-11-12' },
  { id: 'account-calendars', kind: 'connect', title: 'iCloud, Fastmail and Yahoo calendars', why: 'Add the email account and its calendars are offered under Calendars: tick the ones you want, no link to copy. Uses the same app password as the mail.', uses: 'all',
    done: (S) => (S.calendars || []).length > 0, open: { pane: 'connections', focus: 'cal-card' }, added: '2026-11-04' },
  { id: 'recurring-costs', kind: 'feature', title: 'Recurring costs, by project', why: 'Money, Recurring costs: everything you pay again and again (rent, hosting, software, insurance) with what it comes to a month and a year, split by project; each project\'s page shows its own. Charges in your email that come back each month are offered to add in one click.', uses: 'all', open: { go: '#money', hint: 'Recurring costs is under the tiles on Money. Add opens a short form on the right.' }, added: '2026-11-04' },
  { id: 'note-marks', kind: 'feature', title: 'See which notes went to a session', why: 'A note line you sent to a Claude Code session, however it got there, shows where it went and when Claude finished its turn on it. You check it and tick it off: Mark done crosses it out.', uses: ['code'], open: { go: '#notes', hint: 'Send a line to a session; its mark shows after the line.' }, added: '2026-11-06' },
  { id: 'notes-start-session', kind: 'feature', title: 'Send a note to a session that is not running', why: 'Send to session in Notes no longer needs a session open: it offers Start a session in the folders of the note\'s project (or any folder), starts it, and your note goes in as soon as the agent is ready.', uses: ['code'], open: { go: '#notes', hint: 'Open a page and press Send to session: folders with no session open are at the end of the list.' }, added: '2026-11-06' },
  { id: 'session-orchestra', kind: 'feature', title: 'One session runs the others', why: 'Ask the session you are talking to to bring in others: it can start a session in another folder or repo with a first message, read what it answered, and end it when the work is done. Every session it starts shows in Sessions like one you started; it can only end its own.', uses: ['code'], open: { go: '#sessions', hint: 'In any session, ask: "start a session in my-app to fix the header and tell me what it finds".' }, added: '2026-11-06' },
  { id: 'cmdk-voice', kind: 'feature', title: 'Talk to type in Ctrl K', why: 'The mic beside the Ctrl K box: say a note, a reminder, or "sesh" and what to send to a session. Enter stops the mic so you can check the words; Enter again sends.', uses: ['code', 'work', 'business', 'family', 'homestead'], open: { cmd: true }, added: '2026-11-06' },
  { id: 'session-new-folder', kind: 'feature', title: 'Start a session in a new folder', why: 'New session has New folder… at the top of the folder list: for a new client or idea with no repo yet. Switchboard makes the folder in your code folder, ready to keep its history (and a private copy on GitHub if you tick it) and starts the session there.', uses: ['code'], open: { go: '#sessions', hint: 'New session, then Folder: New folder… is first in the list.' }, added: '2026-11-06' },
  { id: 'queue-send-now', kind: 'feature', title: 'Queued messages: Send now and Edit', why: 'A message waiting in a session\'s queue can go in right away (Send now), or come back into the message bar to change (Edit) instead of being thrown away. In Terminal view a click reaches the agent, so a helper it started opens with a click and Esc comes back; End stops everything the session started.', uses: ['code'], open: { go: '#sessions', hint: 'Queue a message while a session works: Send now and Edit are on its line above the message bar.' }, added: '2026-11-06' },
  { id: 'helpers-turn', kind: 'feature', title: 'Your turn means done', why: 'A session that sent helpers (sub-agents) off to work no longer says Your turn while they are still going: it stays Working with "2 helpers still working" until the last one is back. End on a session\'s bar asks once, in place, and waits for your answer.', uses: ['code'], open: { go: '#sessions', hint: 'Open a session: Stop (interrupts what it is doing, the session stays) and End sit on its bar.' }, added: '2026-11-04' },
];
